 var body:some View {
  Group {
   if mode.hasPrefix("reader"){NavigationStack{MangaReader(client:client,item:RemoteTitle(id:"synthetic-reader",kind:"manga",title:"Synthetic Reader",overview:"Fixture pages only",posterURL:nil),chapters:[RemoteDetails.Chapter(id:String(repeating:"0",count:26),number:1,title:"Fixture chapter",language:"en",edition:"official"),RemoteDetails.Chapter(id:String(repeating:"1",count:26),number:2.5,title:"Fixture bonus",language:"en",edition:"official")])}}
   else if mode=="touch-baseline"{BaselineCatalogueFixture(client:client)}
   else if mode=="switching-e2e40"{NativeSwitchingFixture(client:client)}
   else if mode.hasPrefix("native-progress-"){NativeProgressFixture(client:client,mode:mode)}
   else if mode=="connection"{ConnectionView()}
   else if mode.hasPrefix("cast-"){CastReceiverPicker(client:client){_ in}}
   else if mode.hasPrefix("details"){NavigationStack{RemoteDetailView(client:client,item:RemoteTitle(id:"1",kind:mode.hasSuffix("-tv") ? "tv":"movie",title:"The Last Horizon",overview:"A synthetic story used to inspect the interface.",posterURL:nil))}}
   else if mode=="unified-phone"{RemoteControlView(client:client,initialSelection:PhonePlaybackSelection(kind:"movie",contentID:1,season:nil,episode:nil),initialItem:RemoteTitle(id:"1",kind:"movie",title:"Synthetic silent clip",overview:"",posterURL:nil),startsOnPhone:true)}
   else if mode.hasPrefix("transfer-e2e"){NativeTransferFixture(client:client,cancel:mode.contains("cancel"))}
   else if mode=="remote" || mode=="remote-cancel"{RemoteControlView(client:client)}
   else if mode.hasPrefix("downloads"){RemoteDownloadsView(client:client)}
   else if mode=="rating45"{RatingClippingFixture()}
   else{RemoteHomeView(client:client)}
  }.onAppear{TouchVerification.install()}.dynamicTypeSize(mode=="header-large" ? .accessibility1:.large).safeAreaInset(edge:.top){if !mode.hasPrefix("header") && mode != "pagination"{Text("PREVIEW · SYNTHETIC FIXTURES").font(.caption2.weight(.semibold)).foregroundStyle(.secondary).frame(maxWidth:.infinity).padding(4)}}
 }
}
@MainActor private struct NativeTransferFixture:View {
 let client:RemoteClient;let cancel:Bool
 @State private var phone=PhonePlaybackModel()
 @State private var transaction=DestinationTransferModel()
 @State private var result="Testing native transaction…"
 var body:some View{Text(result).padding().task{
  UIOnlyProtocol.resetTransferProbe()
  UIOnlyProtocol.probe(["nativeTransferError":"none","nativeTransferRoundTripPassed":false,"nativeTransferCancelled":false,"nativeTransferPhoneReady":false])
  do{
   if cancel{
    let operation=Task{try await transaction.transfer(client,origin:"mac",destination:"phone",phone:phone,title:"Synthetic silent clip")}
    if ProcessInfo.processInfo.arguments.contains("transfer-e2e-cancel-commit"){
     let deadline=ContinuousClock.now.advanced(by:.seconds(10))
     while !UIOnlyProtocol.transferCommitSent{guard ContinuousClock.now<deadline else{operation.cancel();throw RemoteFailure(message:"Native commit was never reached")};try await Task.sleep(for:.milliseconds(20))}
    }
    try await Task.sleep(for:.milliseconds(50));transaction.cancel(client);operation.cancel()
    do{try await operation.value;throw RemoteFailure(message:"Cancelled transaction unexpectedly succeeded")}catch{guard error is CancellationError || (error as? URLError)?.code == .cancelled else{throw error}}
    let state:PlaybackStatus=try await client.request("/remote/v1/status")
    guard state.state=="paused",abs(state.position-0.5)<1,!phone.ready else{throw RemoteFailure(message:"Cancellation did not preserve the origin")};UIOnlyProtocol.probe(["nativeTransferCancelledAtCommit":UIOnlyProtocol.transferCommitSent,"nativeTransferCancelled":true,"nativeTransferOriginPaused":state.state=="paused","nativeTransferPhoneReady":phone.ready]);result="Cancellation passed"
   }else{
    try await transaction.transfer(client,origin:"mac",destination:"phone",phone:phone,title:"Synthetic silent clip")
    let position=phone.player.currentTime().seconds
    UIOnlyProtocol.probe(["nativeTransferPhoneReady":phone.ready,"nativeTransferPhonePaused":phone.player.rate==0,"nativeTransferPhonePosition":position])
    try await transaction.transfer(client,origin:"phone",destination:"mac",phone:phone,title:"Synthetic silent clip")
    let state:PlaybackStatus=try await client.request("/remote/v1/status")
    UIOnlyProtocol.probe(["nativeTransferRoundTripPassed":!phone.ready && state.state=="paused" && abs(state.position-position)<1,"nativeTransferMacPosition":state.position]);result="Native round trip passed"
   }
  }catch{result=error.localizedDescription;UIOnlyProtocol.probe(["nativeTransferError":error.localizedDescription])}
 }}
}
